// MarkEventProcessed stamps a trigger event processed, but only once
// (COALESCE keeps the first timestamp). Returns the row so the caller can tell a
// first processing from a repeat.
func (q *Queries) MarkEventProcessed(ctx context.Context, arg MarkEventProcessedParams) error {
	_, err := q.db.Exec(ctx, markEventProcessed, arg.ProcessedAt, arg.SessionID, arg.ID)
	return err
}

