const maxEventSeq = `-- name: MaxEventSeq :one
SELECT COALESCE(MAX(seq), 0)::bigint AS max_seq
FROM events
WHERE session_id = $1
`

// MaxEventSeq returns the current highest receipt sequence for a session, or 0
// when the session has no events yet. Called while holding the admission lock.
func (q *Queries) MaxEventSeq(ctx context.Context, sessionID string) (int64, error) {
	row := q.db.QueryRow(ctx, maxEventSeq, sessionID)
	var max_seq int64
	err := row.Scan(&max_seq)
	return max_seq, err
}

const priorProcessedModelTriggers = `-- name: PriorProcessedModelTriggers :many
SELECT event.id, event.session_id, event.seq, event.type, event.payload, event.turn_event_id, event.created_at, event.processed_at, event.thread_id
FROM events AS event
WHERE event.session_id = $1
  AND event.thread_id = (
      SELECT thread.id FROM session_threads AS thread
      WHERE thread.session_id = $1 AND thread.kind = 'primary'
  )
  AND event.type IN ('user.message', 'user.custom_tool_result', 'user.tool_confirmation')
  AND event.processed_at IS NOT NULL
  AND event.seq < $2
ORDER BY event.seq
`

type PriorProcessedModelTriggersParams struct {
	SessionID string
	BeforeSeq int64
}

// PriorProcessedModelTriggers returns processed events that can drive a model
// turn before a given sequence, in receipt order. Resolution events are included
// because a completed custom-tool/confirmation resume may itself have committed
// model output that later turns must replay.
func (q *Queries) PriorProcessedModelTriggers(ctx context.Context, arg PriorProcessedModelTriggersParams) ([]Event, error) {
	rows, err := q.db.Query(ctx, priorProcessedModelTriggers, arg.SessionID, arg.BeforeSeq)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Event{}
	for rows.Next() {
		var i Event
		if err := rows.Scan(
			&i.ID,
			&i.SessionID,
			&i.Seq,
			&i.Type,
			&i.Payload,
			&i.TurnEventID,
			&i.CreatedAt,
			&i.ProcessedAt,
			&i.ThreadID,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

